"""System state page (todo #170): `~/ultron/esprit/etat.md`, regenerated by script, no AI.

One short page any session can read first: focus, branches ready to merge (and in which order), what waits for the user,
merges of the last 24 h, after-merge steps not done. Regenerated after every merge (`branch merge`,
`branch merge-lot`) and by the 8 o'clock digest. Best effort when called from those places: a failure never breaks them.
Size capped to `MAX_BYTES` (budget of check 19 of the housekeeping, config/menage.yaml).
"""

from __future__ import annotations

import subprocess
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any, Callable

from ultron_hub.common.logging import get_logger
from ultron_hub.common.settings import Settings
from ultron_hub.esprit import focus, store

log = get_logger("esprit-etat")

FILE = "etat.md"
MAX_BYTES = 4096
HOURS = 24
CAPS = (8, 5, 3, 2, 1)  # lines per section, tried in turn until the page fits
NO_AI = "Page générée par script (`ultron-hub esprit etat`), sans IA ; ne pas éditer à la main."


def _git_merge_tree(path: Path, branch: str, main: str) -> bool | None:
    """True = merges cleanly into main, False = conflicts, None = unknown."""
    from ultron_hub import branches  # lazy: branches imports the esprit store
    try:
        proc = subprocess.run(["git", "-C", str(path), "merge-tree", "--write-tree", main, branch],
                              capture_output=True, text=True, timeout=branches.GIT_TIMEOUT_S, env=branches._env(),
                              check=False)
    except (OSError, subprocess.SubprocessError):
        return None
    return {0: True, 1: False}.get(proc.returncode)


def _branches(settings: Settings) -> list[dict[str, Any]]:
    from ultron_hub import branch_lot, branches  # lazy
    found = [b for b in branch_lot._all_branches(settings) if b["ahead"]]
    parents = branch_lot._parents(found)
    rank = {tid: i for i, tid in enumerate(branch_lot._order({b["todo_id"] for b in found}, parents))}
    out = []
    for b in sorted(found, key=lambda b: (rank[b["todo_id"]], b["repo"], b["branch"])):
        out.append({"todo": b["todo_id"], "repo": b["repo"], "branch": b["branch"], "sha": b["sha"][:7],
                    "ahead": b["ahead"], "clean": _git_merge_tree(b["path"], b["branch"], branches.MAIN),
                    "after": sorted(parents.get(b["todo_id"], ()))})
    return out


def _atoi(settings: Settings) -> list[dict[str, Any]]:
    from ultron_hub.chantier import core  # lazy: chantier imports the todo package
    return core.atoi(settings, core.sources())["items"]


def _when(text: Any, now: datetime) -> datetime | None:
    try:
        when = datetime.fromisoformat(str(text))
    except ValueError:
        return None
    return when if when.tzinfo else when.replace(tzinfo=now.tzinfo)


def _journal(settings: Settings, now: datetime) -> list[dict[str, Any]]:
    since = now - timedelta(hours=HOURS)
    rows = []
    for entry in store._all_entries(store.root(settings)):
        when = _when(entry.get("date"), now)
        if when and when >= since and entry.get("type") in ("fusion", "livraison"):
            rows.append(entry)
    return rows


def _after_merge(settings: Settings) -> list[dict[str, Any]]:
    from ultron_hub import after_merge  # lazy
    out = []
    folder = settings.var_dir / "after-merge"
    for path in sorted(folder.glob("todo-*.json")) if folder.is_dir() else []:
        try:
            tid = int(path.stem.split("-", 1)[1])
            todo = after_merge.pending(after_merge.load(settings, tid)["actions"])
        except (ValueError, OSError, KeyError):
            continue
        if todo:
            out.append({"todo": tid, "actions": [str(a.get("action", "?")) for a in todo]})
    return out


def _safe(name: str, fn: Callable[[], Any], default: Any, problems: list[str]) -> Any:
    try:
        return fn()
    except Exception as exc:  # noqa: BLE001 — one unreadable source never hides the others
        log.warning("etat: %s illisible (%s)", name, type(exc).__name__)
        problems.append(name)
        return default


def collect(settings: Settings, now: datetime | None = None) -> dict[str, Any]:
    now = now or datetime.fromisoformat(store.now_iso(settings))
    problems: list[str] = []
    return {"now": now, "focus": _safe("focus", lambda: focus.read(settings), None, problems),
            "branches": _safe("branches", lambda: _branches(settings), [], problems),
            "atoi": _safe("à toi", lambda: _atoi(settings), [], problems),
            "journal": _safe("journal", lambda: _journal(settings, now), [], problems),
            "apres": _safe("après-fusion", lambda: _after_merge(settings), [], problems), "problems": problems}


def _cap(lines: list[str], cap: int) -> list[str]:
    return lines if len(lines) <= cap else lines[:cap - 1] + [f"- … et {len(lines) - cap + 1} autre(s)"]


def _text(s: Any, n: int = 70) -> str:
    s = " ".join(str(s).split())
    return s if len(s) <= n else s[:n - 1] + "…"


def render(data: dict[str, Any], cap: int = CAPS[0]) -> str:
    now: datetime = data["now"]
    out = [f"# État du système — {now:%d/%m/%Y %H:%M}", NO_AI, ""]
    fo = data["focus"]
    since = (fo or {}).get("depuis", "")
    day = f" (depuis le {since[8:10]}/{since[5:7]})" if len(since) >= 10 else ""
    out += ["## Focus de la semaine", f"- {' + '.join(fo['domaines'])}{day}" if fo else "- aucun", ""]
    rows = [f"{i}. #{b['todo']} {b['branch']} {b['sha']} · "
            f"{'sans conflit' if b['clean'] else 'CONFLIT' if b['clean'] is False else 'conflit inconnu'}"
            + (f" · après #{', #'.join(map(str, b['after']))}" if b["after"] else "")
            for i, b in enumerate(data["branches"], 1)]
    out += ["## Branches à fusionner (dans cet ordre)"] + (_cap(rows, cap) or ["- aucune"]) + [""]
    groups: dict[str, list[str]] = {}
    for it in data["atoi"]:
        ref = f"#{it['todo']} " if it.get("todo") else ""
        groups.setdefault(it["icone"], []).append(f"{ref}{_text(it['texte'], 55)}")
    rows = [f"- {icon} {len(items)} : " + " ; ".join(_cap(items, 3 if cap > 2 else 1)) for icon, items in groups.items()]
    out += ["## Attend l'utilisateur"] + (_cap(rows, cap) or ["- rien"]) + [""]
    rows = [f"- {e['date'][8:10]}/{e['date'][5:7]} {e['date'][11:16]} {_text(e.get('texte', ''), 90)}"
            for e in data["journal"][::-1]]
    out += [f"## Fusions et livraisons ({HOURS} h)"] + (_cap(rows, cap) or ["- aucune"]) + [""]
    rows = [f"- #{a['todo']} : {', '.join(a['actions'])}" for a in data["apres"]]
    out += ["## Après-fusion non fait"] + (_cap(rows, cap) or ["- rien"])
    if data["problems"]:
        out += ["", "Sources illisibles : " + ", ".join(data["problems"])]
    return "\n".join(out) + "\n"


def fit(data: dict[str, Any]) -> str:
    """The page, with fewer lines per section until it fits `MAX_BYTES`; hard cut as a last resort."""
    for cap in CAPS:
        text = render(data, cap)
        if len(text.encode()) <= MAX_BYTES:
            return text
    cut = text.encode()[:MAX_BYTES - 40].decode(errors="ignore")
    return cut.rsplit("\n", 1)[0] + "\n- … page tronquée\n"


def regenerate(settings: Settings, now: datetime | None = None) -> dict[str, Any]:
    """Write `etat.md` (the esprit folder must exist). Returns {"path", "bytes"}."""
    folder = store._existing(settings)
    text = fit(collect(settings, now))
    with store._locked(folder):
        store._write_atomic(folder / FILE, text)
    return {"path": str(folder / FILE), "bytes": len(text.encode())}


def refresh(settings: Settings) -> None:
    """Best effort for the call sites (after a merge, 8 o'clock digest): nothing when the esprit is absent, never raises."""
    try:
        if store.root(settings).is_dir():
            regenerate(settings)
    except Exception:  # noqa: BLE001
        log.warning("etat: not regenerated", exc_info=True)
